-- The written Au pair process: statuses, the move off the provisional list of
-- 1.8.7, document types, requirements and the registration contact. Run in psql
-- on the VPS after migrations 0089 and 0090, before the code that offers the
-- Au pair tab goes out. Safe to run twice, and on a database that loaded the
-- provisional list. Generated by scripts/au-pair-sql.ts.
BEGIN;

-- 1. Statuses of the written process, inserted where missing.

-- 2. Files on a provisional status the guide drops go to the nearest new step,
-- each with a line in its status history (by the first super admin).
CREATE TEMP TABLE au_pair_moved (application_id text, from_code text, to_code text, from_id text, to_id text) ON COMMIT DROP;
WITH moved AS (UPDATE applications a SET status_id = (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'PROFILE_SUBMITTED'), status_changed_at = now(), updated_at = now() WHERE a.status_id IN (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'AGENCY_PROFILE') AND EXISTS (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'PROFILE_SUBMITTED') RETURNING a.id) INSERT INTO au_pair_moved SELECT id, 'AGENCY_PROFILE', 'PROFILE_SUBMITTED', (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'AGENCY_PROFILE'), (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'PROFILE_SUBMITTED') FROM moved;
WITH moved AS (UPDATE applications a SET status_id = (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'PROFILE_SUBMITTED'), status_changed_at = now(), updated_at = now() WHERE a.status_id IN (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'FAMILY_MATCHING') AND EXISTS (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'PROFILE_SUBMITTED') RETURNING a.id) INSERT INTO au_pair_moved SELECT id, 'FAMILY_MATCHING', 'PROFILE_SUBMITTED', (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'FAMILY_MATCHING'), (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'PROFILE_SUBMITTED') FROM moved;
WITH moved AS (UPDATE applications a SET status_id = (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'VISA_PROCESSING'), status_changed_at = now(), updated_at = now() WHERE a.status_id IN (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'VISA_FILED') AND EXISTS (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'VISA_PROCESSING') RETURNING a.id) INSERT INTO au_pair_moved SELECT id, 'VISA_FILED', 'VISA_PROCESSING', (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'VISA_FILED'), (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'VISA_PROCESSING') FROM moved;
WITH moved AS (UPDATE applications a SET status_id = (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'HAPPY_CALL'), status_changed_at = now(), updated_at = now() WHERE a.status_id IN (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'JOINED' AND label = 'Arrived: living with the host family') AND EXISTS (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'HAPPY_CALL') RETURNING a.id) INSERT INTO au_pair_moved SELECT id, 'JOINED', 'HAPPY_CALL', (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'JOINED' AND label = 'Arrived: living with the host family'), (SELECT id FROM status_definitions WHERE pathway = 'AU_PAIR' AND code = 'HAPPY_CALL') FROM moved;
SELECT 'Moved ' || from_code || ' to ' || to_code || ': ' || count(*) FROM au_pair_moved GROUP BY from_code, to_code ORDER BY from_code;
SELECT 'Au pair applications moved off provisional statuses: ' || count(*) FROM au_pair_moved;

-- 3. The guide's wording and order on the chain. The closing statuses are left as they are.
UPDATE status_definitions SET label = 'Enquiry and initial counselling', student_label = 'Talking through the Au pair programme with your counsellor', student_label_ml = NULL, "group" = 'NEW', sort_order = 10, requires_reason = false, is_milestone = false, active = true WHERE pathway = 'AU_PAIR' AND code = 'ASSESSMENT';
UPDATE status_definitions SET label = 'Registration and agreement', student_label = 'Registering with us', student_label_ml = NULL, "group" = 'NEW', sort_order = 14, requires_reason = false, is_milestone = false, active = true WHERE pathway = 'AU_PAIR' AND code = 'REGISTRATION';
UPDATE status_definitions SET label = 'Document collection by the counsellor', student_label = 'Send us your documents', student_label_ml = NULL, "group" = 'NEW', sort_order = 22, requires_reason = false, is_milestone = false, active = true WHERE pathway = 'AU_PAIR' AND code = 'DOCUMENT_COLLECTION';
UPDATE status_definitions SET label = 'With the documentation department: mentor to be assigned', student_label = 'Our documentation team is choosing your mentor', student_label_ml = NULL, "group" = 'IN_PROGRESS', sort_order = 24, requires_reason = false, is_milestone = true, active = true WHERE pathway = 'AU_PAIR' AND code = 'MENTOR_ASSIGNMENT';
UPDATE status_definitions SET label = 'Interview preparation with the mentor', student_label = 'Practising for your host family interviews', student_label_ml = NULL, "group" = 'IN_PROGRESS', sort_order = 30, requires_reason = false, is_milestone = false, active = true WHERE pathway = 'AU_PAIR' AND code = 'INTERVIEW_PREPARATION';
UPDATE status_definitions SET label = 'Profile submitted with consent: looking for a host family', student_label = 'We are looking for a host family for you', student_label_ml = NULL, "group" = 'IN_PROGRESS', sort_order = 35, requires_reason = false, is_milestone = true, active = true WHERE pathway = 'AU_PAIR' AND code = 'PROFILE_SUBMITTED';
UPDATE status_definitions SET label = 'Host family interested: to hand to the placement team', student_label = 'A host family is interested in you', student_label_ml = NULL, "group" = 'IN_PROGRESS', sort_order = 38, requires_reason = false, is_milestone = true, active = true WHERE pathway = 'AU_PAIR' AND code = 'HOST_FAMILY_FOUND';
UPDATE status_definitions SET label = 'Placement team: host family interview', student_label = 'Your interview with a host family', student_label_ml = NULL, "group" = 'IN_PROGRESS', sort_order = 40, requires_reason = false, is_milestone = true, active = true WHERE pathway = 'AU_PAIR' AND code = 'FAMILY_INTERVIEW';
UPDATE status_definitions SET label = 'Selected by the host family: contract in hand', student_label = 'A host family has chosen you', student_label_ml = NULL, "group" = 'OFFER', sort_order = 45, requires_reason = false, is_milestone = true, active = true WHERE pathway = 'AU_PAIR' AND code = 'OFFER_RECEIVED';
UPDATE status_definitions SET label = 'Host family contract signed', student_label = 'Contract signed', student_label_ml = 'കരാർ ഒപ്പിട്ടു', "group" = 'OFFER', sort_order = 50, requires_reason = false, is_milestone = true, active = true WHERE pathway = 'AU_PAIR' AND code = 'CONTRACT_SIGNED';
UPDATE status_definitions SET label = 'Visa team: pre-visa documentation and payment verification', student_label = 'Preparing your visa file', student_label_ml = NULL, "group" = 'IN_PROGRESS', sort_order = 55, requires_reason = false, is_milestone = false, active = true WHERE pathway = 'AU_PAIR' AND code = 'PRE_VISA_DOCUMENTS';
UPDATE status_definitions SET label = 'Visa appointment booked', student_label = 'Your visa appointment is booked', student_label_ml = NULL, "group" = 'IN_PROGRESS', sort_order = 58, requires_reason = false, is_milestone = true, active = true WHERE pathway = 'AU_PAIR' AND code = 'VISA_APPOINTMENT';
UPDATE status_definitions SET label = 'Visa processing and follow-up', student_label = 'Your visa is being processed', student_label_ml = NULL, "group" = 'IN_PROGRESS', sort_order = 60, requires_reason = false, is_milestone = false, active = true WHERE pathway = 'AU_PAIR' AND code = 'VISA_PROCESSING';
UPDATE status_definitions SET label = 'Visa approved', student_label = 'Visa approved', student_label_ml = 'വിസ ലഭിച്ചു', "group" = 'SUCCESS', sort_order = 65, requires_reason = false, is_milestone = true, active = true WHERE pathway = 'AU_PAIR' AND code = 'VISA_RECEIVED';
UPDATE status_definitions SET label = 'Travel desk: pre-departure preparation', student_label = 'Getting you ready to travel', student_label_ml = NULL, "group" = 'SUCCESS', sort_order = 70, requires_reason = false, is_milestone = true, active = true WHERE pathway = 'AU_PAIR' AND code = 'PRE_DEPARTURE';
UPDATE status_definitions SET label = 'Departed for Germany', student_label = 'On your way to your host family', student_label_ml = NULL, "group" = 'SUCCESS', sort_order = 75, requires_reason = false, is_milestone = true, active = true WHERE pathway = 'AU_PAIR' AND code = 'JOINED';
UPDATE status_definitions SET label = 'Arrived in Germany: post-arrival follow-up', student_label = 'Settling in with your host family: we stay in touch', student_label_ml = NULL, "group" = 'SUCCESS', sort_order = 80, requires_reason = false, is_milestone = false, active = true WHERE pathway = 'AU_PAIR' AND code = 'HAPPY_CALL';

-- 4. Provisional codes no longer used: deactivated, never deleted, and moved to the end of the list.
UPDATE status_definitions SET active = false, sort_order = sort_order + 900 WHERE pathway = 'AU_PAIR' AND code = 'AGENCY_PROFILE' AND active;
UPDATE status_definitions SET active = false, sort_order = sort_order + 900 WHERE pathway = 'AU_PAIR' AND code = 'FAMILY_MATCHING' AND active;
UPDATE status_definitions SET active = false, sort_order = sort_order + 900 WHERE pathway = 'AU_PAIR' AND code = 'VISA_FILED' AND active;

-- 5. Document types the requirements name, inserted only where missing.

-- The two provisional requirements, brought to the guide only while they read as 1.8.7 wrote them.
UPDATE document_requirements SET required = true, guidance = 'Resume / CV. Childcare experience first: babysitting, siblings, teaching, volunteering.' WHERE pathway = 'AU_PAIR' AND type_code = 'CV' AND source = 'ALWAYS' AND required = true AND guidance = 'Childcare experience first: babysitting, siblings, teaching, volunteering.';
UPDATE document_requirements SET required = true, guidance = 'German language certificates, module-wise where the candidate has them, with the level and the year of completion.' WHERE pathway = 'AU_PAIR' AND type_code = 'GERMAN_CERTIFICATE' AND source = 'ALWAYS' AND required = false AND guidance = 'German or another language certificate, where the student has one.';

-- Requirements. Guarded by type, source and pathway: a document is asked for once
-- per pathway, and a row the team has since edited is left as it is.

-- 6. The registration address on the Contacts list, where it is not there yet.

-- What is there now.
SELECT 'AU_PAIR statuses active ' || count(*) FROM status_definitions WHERE pathway = 'AU_PAIR' AND active
UNION ALL SELECT 'AU_PAIR statuses retired ' || count(*) FROM status_definitions WHERE pathway = 'AU_PAIR' AND NOT active
UNION ALL SELECT 'AU_PAIR applications on a retired status ' || count(*) FROM applications a JOIN status_definitions s ON s.id = a.status_id WHERE s.pathway = 'AU_PAIR' AND NOT s.active
UNION ALL SELECT 'AU_PAIR requirements ' || count(*) FROM document_requirements WHERE pathway = 'AU_PAIR' AND active
UNION ALL SELECT 'Au pair contacts ' || count(*) FROM team_contacts WHERE area = 'Au pair (Germany)';

COMMIT;

